PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE reviews (
          id TEXT PRIMARY KEY NOT NULL,
          user_id TEXT NOT NULL,
          product_slug TEXT NOT NULL,
          product_name TEXT NOT NULL,
          username TEXT NOT NULL,
          rating REAL NOT NULL,
          category_ratings TEXT NOT NULL,
          title TEXT NOT NULL,
          body TEXT NOT NULL,
          pros TEXT NOT NULL,
          cons TEXT NOT NULL,
          date TEXT NOT NULL,
          ownership TEXT NOT NULL,
          category TEXT NOT NULL
        , status TEXT NOT NULL DEFAULT 'published', photo_key TEXT, photo_name TEXT, photo_type TEXT, photo_size REAL);
INSERT INTO reviews VALUES('review-6e8c0ed7-2a5a-481e-bf0c-35dd6d2101b5','account-1f274e52-68d7-4c20-8784-0002353c6d7a','custom-poco-f7','Poco F7','idea-house',4.700000000000000177,'{"performance":5,"camera":2.9,"battery":4.4,"display":4,"value":5}','It''s a Performance Beast.',unistr('POCO F7 ဟာ Performance ကို အဓိကထားတဲ့ Flagship Killer ဖုန်းတစ်လုံးဖြစ်ပြီး Gaming၊ Multitasking နဲ့ Video ကြည့်တာတွေမှာ အထူးသင့်တော်ပါတယ်။ Camera ထက် Speed၊ Battery နဲ့ Display ကို ဦးစားပေးသူတွေအတွက် တန်ဖိုးရှိတဲ့ ရွေးချယ်မှုပါ။\u000a\u000a6.83 လက်မ AMOLED Display (1.5K, 120Hz) ကြောင့် ရုပ်ထွက်ကြည်လင်ပြီး အသုံးပြုရာမှာ ချောမွေ့ပါတယ်။ Snapdragon 8s Gen 4, 12GB RAM နဲ့ UFS 4.1 Storage ပါဝင်တာကြောင့် App အသုံးပြုမှုနဲ့ Gaming တွေမှာ လျင်မြန်ပြီး Lag နည်းပါတယ်။\u000a\u000a50MP Main Camera (OIS) က နေ့ဘက်ဓာတ်ပုံတွေကောင်းပေမယ့် Ultra-wide က ပုံမှန်သာဖြစ်ပါတယ်။ 20MP Front Camera က Selfie အတွက် လုံလောက်ပါတယ်။\u000a\u000a6,500mAh Battery နဲ့ 90W Fast Charging ပါဝင်တာကြောင့် အသုံးခံပြီး အားသွင်းမြန်ပါတယ်။ Android 15 အခြေခံ HyperOS 2, IP68, Stereo Speakers စတဲ့ Features တွေပါဝင်ပြီး စုစုပေါင်းအားဖြင့် Performance ကို ဦးစားပေးသူတွေအတွက် အလွန်တန်ဖိုးရှိတဲ့ ဖုန်းတစ်လုံးဖြစ်ပါတယ်။'),'["Snapdragon 8s Gen 4","Flagship-level Performance","Excellent AMOLED Display","6500mAh Battery","90W Fast Charge","Premium Build","IP68","Great Stereo Speakers","Excellent Value for Money"]','["Telephoto Camera မပါ","Ultra-wide Camera သာမန်အဆင့်","Wireless Charging မပါ","အလေးချိန်များ","HyperOS တွင် Bloatware အနည်းငယ်ရှိနိုင်"]','2026-07-23T10:12:52.369Z','1-3 months','Smartphones','published','reviews/review-6e8c0ed7-2a5a-481e-bf0c-35dd6d2101b5/a5ff7960-828f-4705-8302-6e10d4a5ac4e','POCO_F7.webp','image/webp',53026.0);
INSERT INTO reviews VALUES('review-b331cd98-a112-4271-a9e9-bc790401c531','account-fd62b1a9-b4ec-4145-b5fe-41fe057b1c79','custom-macbook-air-m4','MacBook Air M4','pyae-zaw',4.599999999999999644,'{"performance":4.7,"camera":3.8,"battery":4.9,"display":4.5,"value":4.6}','The daily driver I actually keep reaching for','I have been using the 13-inch MacBook Air M4 for about four months as my main writing and browsing machine. It stays cool and silent even with a dozen Safari tabs, Notes, and a video call running together. The Liquid Retina panel is bright enough outdoors, and I regularly get a full workday plus some evening YouTube without hunting for a charger. Fanless is the whole point, and M4 finally makes that feel like it has spare power instead of just enough. The MagSafe brick is tiny, which I love for travel. I would still pick this over a Windows ultraportable for sleep/wake and trackpad quality alone.','["Silent fanless chassis","All-day battery in real use","Excellent trackpad and keyboard"]','["Only two Thunderbolt ports","Display is not as punchy as the Pro XDR panel"]','2026-08-13T14:19:16.385Z','4 months','Laptops','published','reviews/review-b331cd98-a112-4271-a9e9-bc790401c531/7ff77a62-039d-4036-9973-60970bb286fe','macbook-air-m4.jpg','image/jpeg',249860.0);
INSERT INTO reviews VALUES('review-1a72dd79-4b07-4d60-831c-7073aa7d5086','account-fd62b1a9-b4ec-4145-b5fe-41fe057b1c79','custom-macbook-pro-m5','MacBook Pro M5','pyae-zaw',4.799999999999999823,'{"performance":5,"camera":4.2,"battery":4.8,"display":5,"value":4.3}','Sustained power when the Air starts to throttle','I moved to the 14-inch MacBook Pro M5 for photo exports, light video, and longer compile jobs. The Mini-LED XDR screen with ProMotion is the first thing I notice every morning: deep blacks, no PWM fuss for me, and it stays readable in mixed lighting. HDMI and the SD card slot still matter when I am dumping cards from the X100VI. Active cooling means exports finish without the machine getting sluggish, which is exactly where the Air used to fade. Battery is still excellent for a Pro, usually 12-plus hours of mixed work. It is heavier in a backpack, and the price jump is real, but for my workload the extra ports and display are worth it.','["XDR display with ProMotion","HDMI and SD card built in","Holds performance under load"]','["Heavier than the Air","Base storage fills up quickly if you shoot RAW"]','2026-08-13T14:19:16.404Z','3 months','Laptops','published','reviews/review-1a72dd79-4b07-4d60-831c-7073aa7d5086/4cd68cd6-31b9-4e0b-b563-af4229b558ae','macbook-pro-m5.jpg','image/jpeg',146028.0);
INSERT INTO reviews VALUES('review-110b0843-b90b-44c0-bca0-a7bc61c275f1','account-fd62b1a9-b4ec-4145-b5fe-41fe057b1c79','custom-iphone-17-pro-max','iPhone 17 Pro Max','pyae-zaw',4.700000000000000177,'{"performance":5,"camera":4.9,"battery":4.8,"display":4.8,"value":4.2}','Big screen, huge battery, camera I actually trust','The iPhone 17 Pro Max is the phone that lives in my pocket most days. The telephoto is the reason I stopped carrying a second camera for trips around town, and night photos hold onto color instead of turning into mush. Battery easily lasts a heavy day of maps, photos, and messaging. The aluminum unibody with the camera plateau looks distinctive in Cosmic Orange, though it does pick up fingerprints. It is a large phone; one-handed typing is a stretch. USB-C charging is fast enough that a short top-up before leaving the house covers me. If you want the most complete iPhone, this is still the one I would buy again.','["Excellent zoom and low light","Two-day battery if you are not hammering it","Bright, smooth ProMotion display"]','["Large and not pocket-friendly in shorts","Premium price for storage upgrades"]','2026-08-13T14:19:16.420Z','6 months','Smartphones','published','reviews/review-110b0843-b90b-44c0-bca0-a7bc61c275f1/b716e0b7-a64c-4d29-a3b0-2bb5b6711451','iphone-17-pro-max.jpg','image/jpeg',184414.0);
INSERT INTO reviews VALUES('review-191a978d-6675-4a1a-bc55-ce40097c73a4','account-fd62b1a9-b4ec-4145-b5fe-41fe057b1c79','custom-iphone-17-pro','iPhone 17 Pro','pyae-zaw',4.599999999999999644,'{"performance":5,"camera":4.8,"battery":4.4,"display":4.7,"value":4.5}','Same Pro cameras in a size I can actually hold','I keep the iPhone 17 Pro as my smaller daily when I do not want the Max in a jacket pocket. Camera IQ is essentially the Pro Max experience for stills, including the useful telephoto, and the A19 Pro chip never feels like it is waiting. Battery is the trade-off: I finish most days with 20-30 percent left, but a very heavy camera-and-maps day needs a pack. The Deep Blue finish hides wear better than I expected. Promotion and the always-on lock screen are still the details I would miss on a non-Pro iPhone. If you want Pro cameras without the slab, this is the balanced pick.','["Pro camera system in a smaller body","Comfortable one-handed use","Flagship performance"]','["Battery is tighter than the Max","Gets warm during long 4K recording"]','2026-08-13T14:19:16.435Z','5 months','Smartphones','published','reviews/review-191a978d-6675-4a1a-bc55-ce40097c73a4/7aae2ff3-eccf-40b9-9185-529875f704eb','iphone-17-pro.jpg','image/jpeg',144074.0);
INSERT INTO reviews VALUES('review-b0f150de-bbb3-45ed-9f13-7009bd20262e','account-fd62b1a9-b4ec-4145-b5fe-41fe057b1c79','custom-xiaomi-17-ultra','Xiaomi 17 Ultra','pyae-zaw',4.5,'{"performance":4.8,"camera":5,"battery":4.6,"display":4.7,"value":4.4}','Leica zoom phone that almost replaces a compact','The Xiaomi 17 Ultra is the most camera-first Android I have owned. The 1-inch class main sensor plus the periscope with the zoom ring make it feel closer to a tool than a phone gimmick. Leica color modes are a taste thing, but the zoomed portraits and distant details are the reason I bring this instead of a second body on city walks. Snapdragon 8 Elite Gen 5 is fast, HyperOS 3 is cleaner than older Xiaomi software, and the 6.9-inch LTPO panel is gorgeous. It is heavy, the camera bump is no joke, and some Google apps still feel like guests on HyperOS. Charging is rapid, which saves the battery from being a deal-breaker.','["Class-leading zoom flexibility","Huge bright LTPO display","Very fast wired charging"]','["Heavy camera bump","Software still has Xiaomi quirks"]','2026-08-13T14:19:16.451Z','2 months','Smartphones','published','reviews/review-b0f150de-bbb3-45ed-9f13-7009bd20262e/ea18eddb-d6e3-4113-bdaa-d5ccc4018cff','xiaomi-17-ultra.jpg','image/jpeg',243616.0);
INSERT INTO reviews VALUES('review-a5a0ef9f-1a33-4791-95d0-7312136abab3','account-fd62b1a9-b4ec-4145-b5fe-41fe057b1c79','custom-fujifilm-x100vi','Fujifilm X100VI','pyae-zaw',4.799999999999999823,'{"performance":4.5,"camera":5,"battery":3.6,"display":4.4,"value":4.3}','The compact I still take when phones are not enough','A popular camera for a reason. The Fujifilm X100VI is the one I grab for weekends because the 23mm lens and film simulations get me shots I actually want to keep, not just ones that look sharp on a phone. IBIS is the upgrade that made it usable in dim cafes, and the hybrid viewfinder still feels special. Autofocus is good enough for people and streets, not sports. Battery life is the weak point; I carry a spare. It is also still hard to find at a sane price. If you like tactile dials and a fixed lens that forces you to move your feet, this remains the compact to beat.','["Beautiful film simulations","IBIS in a pocketable body","Hybrid viewfinder is addictive"]','["Average battery life","Fixed 23mm will not suit everyone"]','2026-08-13T14:19:16.468Z','8 months','Accessories','published','reviews/review-a5a0ef9f-1a33-4791-95d0-7312136abab3/2cd8cb89-6210-4486-9923-7ed25a76327b','fujifilm-x100vi.jpg','image/jpeg',392716.0);
INSERT INTO reviews VALUES('review-afdf73e6-4f4d-444a-af83-941c7a0b0c44','account-fd62b1a9-b4ec-4145-b5fe-41fe057b1c79','custom-nothing-headphone-1','Nothing Headphone (1)','pyae-zaw',4.299999999999999823,'{"performance":4.4,"camera":0,"battery":4.2,"display":0,"value":4.4}','Transparent design, warm sound, easy daily wear','I bought the Nothing Headphone (1) because I wanted over-ears that did not look like every other black pair on the train. ANC is solid for an office and a bus, not class-leading like the expensive Sony flagships, but good enough that I leave them on for focus work. Sound is warm and fun, with enough bass without turning muddy. The transparent cups and yellow hardware still get comments. Comfort is fine for two-hour sessions; after that the clamp shows up. Multipoint with the laptop and phone just works. If you already like Nothing''s aesthetic, these are an easy recommend.','["Distinct look that is not boring","Comfortable for work blocks","Simple app and multipoint"]','["ANC is good, not the best","Clamps a bit on long flights"]','2026-08-13T14:19:16.485Z','3 months','Audio','published','reviews/review-afdf73e6-4f4d-444a-af83-941c7a0b0c44/98e30265-3ef9-4b6f-94eb-6bdd3aeedd0f','nothing-headphone.jpg','image/jpeg',125299.0);
INSERT INTO reviews VALUES('review-ac310737-3ef5-435c-85e6-13fa1e4ab2cf','account-fd62b1a9-b4ec-4145-b5fe-41fe057b1c79','custom-cmf-watch-3-pro','CMF Watch 3 Pro','pyae-zaw',4.099999999999999644,'{"performance":3.9,"camera":0,"battery":4.5,"display":4.2,"value":4.7}','A fun watch that lasts, without a flagship price','The CMF Watch 3 Pro is the wearable I put on when I do not want to spend Apple Watch money. The round AMOLED is bright, the swappable bezels are actually fun, and battery life is the headline: I charge about twice a week with mixed tracking. Heart rate and sleep are directionally useful, not medical. Bluetooth calling works in a pinch. The software is simpler than Wear OS or watchOS, which is both the charm and the limit. For notifications, steps, and a week of battery, it is hard to argue with at this price.','["Strong battery for the money","Customizable bezels and faces","Bright round AMOLED"]','["Health tracking is basic","App ecosystem is limited"]','2026-08-13T14:19:16.499Z','2 months','Wearables','published','reviews/review-ac310737-3ef5-435c-85e6-13fa1e4ab2cf/1c1cba53-f79b-478c-bafa-31e05376dce8','cmf-watch.jpg','image/jpeg',187368.0);
INSERT INTO reviews VALUES('review-3e1b0054-695e-4720-8860-cd75df551eed','account-fd62b1a9-b4ec-4145-b5fe-41fe057b1c79','custom-xiaomi-pad-8-pro','Xiaomi Pad 8 Pro','pyae-zaw',4.400000000000000356,'{"performance":4.7,"camera":3.5,"battery":4.8,"display":4.6,"value":4.7}','A tablet that almost stands in for a laptop','The Xiaomi Pad 8 Pro replaced my old iPad for note-taking and travel media. The 11.2-inch 3.2K 144Hz panel is sharp, and Snapdragon 8 Elite makes split-screen and light editing feel instant. The 9200mAh battery is the star: long-haul flights are not a problem. Workstation mode plus the Focus Keyboard gets surprisingly close to a laptop for docs and browsing. Cameras are there if you need them, not why you buy this. HyperOS tablet software is better than it used to be, though some apps still feel stretched. At this price versus an iPad Air, the hardware is generous.','["Huge battery","Flagship chip in a tablet","Great value versus iPad Air"]','["Tablet apps still trail iPad","Keyboard and pen cost extra"]','2026-08-13T14:19:16.513Z','1-3 months','Accessories','published','reviews/review-3e1b0054-695e-4720-8860-cd75df551eed/3c7184bc-d461-4981-abaf-21428df4b76b','xiaomi-pad-8-pro.jpg','image/jpeg',149333.0);
